	sourceFile?: string;
	sourceUlid?: string;
	field: string;
	error: 'not_found' | 'ambiguous' | 'duplicate_slug';
	message: string;
}

export interface RefValidationWarning {
	ref: string;
	sourceFile?: string;
	sourceUlid?: string;
	field: string;
	warning: 'deprecated_target';
	message: string;
}

export interface OrphanItem {
	ulid: string;
	title: string;
	type: string;
	file?: string;
}

export type CompletenessWarningType =
	| 'missing_acceptance_criteria'
	| 'missing_description'
	| 'status_inconsistency'
	| 'missing_test_coverage'
	| 'automation_eligible_no_spec'
	| 'ac_schema_field_mismatch';

export interface CompletenessWarning {
	type: CompletenessWarningType;
	subtype?: 'own_ac' | 'trait_ac';
	itemRef: string;
	itemTitle: string;
	message: string;
	details?: string;
}

export interface TraitCycleError {
	traitRef: string;
	traitTitle: string;
	cycle: string[];
	message: string;
}

