 70→	function formatDate(dateString: string): string {
 71→		const date = new Date(dateString);
 72→		const now = new Date();
 73→		const diffMs = now.getTime() - date.getTime();
 74→		const diffMins = Math.floor(diffMs / 60000);
 75→		const diffHours = Math.floor(diffMs / 3600000);
 76→		const diffDays = Math.floor(diffMs / 86400000);
 77→
 78→		if (diffMins < 1) return 'just now';
 79→		if (diffMins < 60) return `${diffMins}m ago`;
 80→		if (diffHours < 24) return `${diffHours}h ago`;
 81→		if (diffDays < 7) return `${diffDays}d ago`;
 82→
 83→		return date.toLocaleDateString();
