	const response = await fetch(`${API_BASE}/api/triage`, {
		method: 'POST',
		headers: {
			'Content-Type': 'application/json',
			...getProjectHeaders()
		},
		body: JSON.stringify(data)
	});
	if (!response.ok) {
		await handleResponseError(response);
	}

	return response.json();
}

/**
