 */
export async function overrideTriageRecord(
	ref: string,
	data: {
		action: string;
		reasoning: string;
		override_by?: string;
	}
): Promise<{ success: boolean; record: TriageRecord }> {
	assertWritable('override triage record');

	const response = await fetch(`${API_BASE}/api/triage/${ref}/override`, {
		method: 'POST',
		headers: {
			'Content-Type': 'application/json',
			...getProjectHeaders()
		},
		body: JSON.stringify(data)
	});
	if (!response.ok) {
		await handleResponseError(response);
	}

	return response.json();
}

// ============================================================
// Agent & Dispatch API Functions
// AC: @ui-agent-dispatch ac-1, ac-2, ac-3
// ============================================================

/**
 * Agent definition from GET /api/meta/agents
 */
export interface AgentDefinition {
	_ulid: string;
	id: string;
	name: string;
	description?: string;
	adapter?: string;
	dispatch: Array<{
		on: string;
		filter?: {
			automation?: string;
			tags?: string[];
			priority?: number;
		};
	}>;
	capabilities: string[];
	tools: string[];
	skills: string[];
	budget?: {
		max_tasks?: number;
		timeout_minutes?: number;
	};
	concurrency: {
		max_concurrent: number;
	};
	auto_approve: boolean;
}

/**
 * Active invocation from GET /api/agent/status
